"""Write the layout kit's generated files (ADR-008 D2).

From layout/include/overlay_contract.json (the overlay contract's table),
layout/include/kit/AGENTS.md.tmpl and the kit's samples
(layout/include/kit/<kind>/index.*), write:

- layout/include/kit/CONTRACT.md         the view's keys as tables
- layout/include/kit/<kind>/AI_PROMPT.md one file to paste into a chat AI:
                                          the instructions, the keys the kind
                                          reads and the kind's sample

Both are committed and copied into a new design by core/LayoutKit. Run this
after changing any of the sources:

    python scripts/gen_layout_kit.py

tests/test_layout_kit.py fails when the committed files are not what this
writes (``Build()`` is compared, line endings aside).
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
LAYOUT = ROOT / "layout"
KIT = LAYOUT / "include" / "kit"
CONTRACT = LAYOUT / "include" / "overlay_contract.json"
AGENTS_TEMPLATE = "AGENTS.md.tmpl"
SAMPLE_FILES = ("index.html", "index.css", "index.js")
FENCES = {"index.html": "html", "index.css": "css", "index.js": "js"}

# The kinds a new design may be (core/LayoutKit.KINDS' keys), with their
# page's name and the view's groups they read first.
KINDS = {
    "scoreboard": ("BOARD のスコアボード", ("board", "tournament", "options")),
    "commentary": ("実況者の表示", ("commentary", "tournament", "options")),
    "top8": ("TOP 8 のブラケット", ("top8", "tournament", "options")),
}
GROUP_ORDER = ("board", "tournament", "commentary", "top8", "options")
GROUP_TITLES = {
    "board": "view.board（スコアボード）",
    "tournament": "view.tournament（大会）",
    "commentary": "view.commentary（実況者）",
    "top8": "view.top8（TOP 8）",
    "options": "view.options（表示の切り替え）",
}
HEADER = ("<!-- Generated by scripts/gen_layout_kit.py from "
          "layout/include/overlay_contract.json{sources}. Do not edit: "
          "change the sources and run the script. -->\n")


def _cell(value):
    return str(value).replace("|", "\\|").replace("\n", " ")


def _empty(value):
    return "`" + json.dumps(value, ensure_ascii=False) + "`"


def _group(key):
    return key.split(".", 1)[0].split("[", 1)[0]


def _table(keys):
    lines = ["| キー | 型 | 値が無いとき | 説明 |", "|---|---|---|---|"]
    for row in keys:
        lines.append(f"| `{_cell(row['key'])}` | {row['type']} | "
                     f"{_empty(row['empty'])} | {_cell(row['ja'])} |")
    return "\n".join(lines)


def _sections(contract, groups, level):
    out = []
    for group in groups:
        keys = [row for row in contract["keys"] if _group(row["key"]) == group]
        if keys:
            out.append(f"{'#' * level} {GROUP_TITLES[group]}\n\n{_table(keys)}\n")
    return "\n".join(out)


def _placeholders(contract):
    return "\n".join(
        f"- `{name}`: " + " / ".join(f"`{value}`" for value in values)
        for name, values in contract["placeholders"].items())


def _contract_md(contract):
    return (
        HEADER.format(sources="")
        + f"\n# オーバーレイ契約 {contract['contract']} のキー\n\n"
        + contract["description"]["ja"] + "\n\n"
        + "キーの中の記号:\n\n" + _placeholders(contract) + "\n\n"
        + _sections(contract, GROUP_ORDER, 2))


def _demote(text):
    """Every Markdown heading outside code fences one level down, and the
    document's own title dropped."""
    out = []
    fenced = False
    titled = False
    for line in text.splitlines():
        if line.startswith("```"):
            fenced = not fenced
        elif not fenced and line.startswith("# ") and not titled:
            titled = True
            continue
        elif not fenced and line.startswith("#"):
            line = "#" + line
        out.append(line)
    return "\n".join(out).strip() + "\n"


def _ai_prompt(kind, contract, agents, samples):
    label, groups = KINDS[kind]
    others = [group for group in GROUP_ORDER if group not in groups]
    parts = [
        HEADER.format(sources=", layout/include/kit/AGENTS.md.tmpl and "
                      f"layout/include/kit/{kind}/"),
        f"\n# Autona のオーバーレイを作る: {label}（kind `{kind}`）\n",
        "この文書だけで作れるように、指示書・データのキーの表・動くサンプルをまとめています。"
        "あなた（AI）は利用者の頼みに合わせてサンプルを書き換え、"
        "**`index.html` / `index.css` / `index.js` の全文**をファイルごとに 1 つのコードブロックで返してください。"
        "利用者はそれを Autona の「新しいデザインを作る」で作ったフォルダ（`layout/<フォルダ名>/`）に上書き保存します。"
        "`settings.json` と `../include/` の中身は利用者の手元にあるので、返さなくてよいです。\n",
        "## 指示書\n",
        _demote(agents),
        f"## view のキー（{kind} で使うまとまり）\n",
        "ほかのまとまり（" + "・".join(f"`view.{group}`" for group in others)
        + "）も同じ `view` にあります（キーの全量はフォルダの `CONTRACT.md`）。"
        + "キーの中の記号:\n\n" + _placeholders(contract) + "\n",
        _sections(contract, groups, 3),
        "## サンプル（今フォルダにある 3 ファイル）\n",
    ]
    for name in SAMPLE_FILES:
        parts.append(f"### {name}\n\n```{FENCES[name]}\n"
                     f"{samples[name].rstrip()}\n```\n")
    return "\n".join(parts)


def _read(path):
    # Line endings as git checks them out on Windows do not matter.
    return path.read_text(encoding="utf-8").replace("\r\n", "\n")


def Build(layout=LAYOUT):
    """{path relative to layout/include/kit: text} of every generated file."""
    kit = Path(layout) / "include" / "kit"
    contract = json.loads(_read(Path(layout) / "include"
                                / "overlay_contract.json"))
    agents = _read(kit / AGENTS_TEMPLATE)
    files = {"CONTRACT.md": _contract_md(contract)}
    for kind in KINDS:
        samples = {name: _read(kit / kind / name) for name in SAMPLE_FILES}
        files[f"{kind}/AI_PROMPT.md"] = _ai_prompt(
            kind, contract, agents, samples)
    return files


def main():
    for relative, text in Build().items():
        path = KIT / relative
        path.write_text(text, encoding="utf-8", newline="\n")
        print(f"wrote {path.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
